from pathlib import Path

import pytest

from scripts.verify_hostlist_compiler import compare_rules


def test_hostlist_compiler_validation_accepts_identical_rules_and_ignores_comments(tmp_path):
    source = tmp_path / "source.txt"
    validated = tmp_path / "validated.txt"
    source.write_text(
        "! Title: test\n||ads.example.com^\n@@||safe.example.com^\n",
        encoding="utf-8",
    )
    validated.write_text(
        "||ads.example.com^\n! Generated by Hostlist Compiler\n@@||safe.example.com^\n",
        encoding="utf-8",
    )

    assert compare_rules(source, validated) == 2


def test_hostlist_compiler_validation_rejects_removed_or_changed_rules(tmp_path):
    source = tmp_path / "source.txt"
    validated = tmp_path / "validated.txt"
    source.write_text("||ads.example.com^\n||tracker.example.net^\n", encoding="utf-8")
    validated.write_text("||ads.example.com^\n", encoding="utf-8")

    with pytest.raises(ValueError, match="removed or changed by compiler"):
        compare_rules(source, validated)


def test_hostlist_compiler_validation_rejects_duplicate_source_rules(tmp_path):
    source = tmp_path / "source.txt"
    validated = tmp_path / "validated.txt"
    source.write_text("||ads.example.com^\n||ads.example.com^\n", encoding="utf-8")
    validated.write_text("||ads.example.com^\n", encoding="utf-8")

    with pytest.raises(ValueError, match="duplicate source rules"):
        compare_rules(source, validated)
